async function previewThread(id, provider) { try { state.threadPreview = { itemId: id, provider }; $("thread-preview-provider").textContent = provider === "chatgpt" ? "ChatGPT" : "Gemini"; $("thread-preview-title").textContent = "Reading shared thread…"; $("thread-preview-text").textContent = ""; $("thread-preview-media").textContent = ""; $("thread-import-material").disabled = true; $("thread-learn-material").disabled = true; $("thread-preview-dialog").showModal(); const result = await api("/api/item-intake/threads/preview", { method: "POST", body: JSON.stringify({ item_id: id, provider }) }); $("thread-preview-title").textContent = result.preview.page_title || "Shared thread"; $("thread-preview-text").textContent = result.preview.text_preview || "No readable text was returned."; $("thread-preview-media").textContent = `${result.preview.image_count || 0} image(s) available for extraction.`; $("thread-import-material").disabled = false; $("thread-learn-material").disabled = false; } catch (error) { if ($("thread-preview-dialog").open) $("thread-preview-dialog").close(); toast(`Thread preview failed: ${error.message}`); } }
