async function importThreadMaterial() { const preview = state.threadPreview; if (!preview) return; $("thread-import-material").disabled = true; try { const result = await api("/api/item-intake/threads/import", { method: "POST", body: JSON.stringify({ item_id: preview.itemId, provider: preview.provider, confirm: true }) }); $("thread-preview-dialog").close(); state.details.set(preview.itemId, result.imported.item); await load(state.activeBatchId); await openItem(preview.itemId); toast(`Imported thread text and ${result.imported.photos?.length || 0} image(s) into this item.`); } catch (error) { $("thread-import-material").disabled = false; toast(`Thread extraction failed: ${error.message}`); } }
async function learnThreadMaterial() { const preview = state.threadPreview; if (!preview) return; if (!confirm("Extract this reviewed thread, then send the item brief to Veridex for learning?")) return; $("thread-import-material").disabled = true; $("thread-learn-material").disabled = true; try { const result = await api("/api/item-intake/threads/import", { method: "POST", body: JSON.stringify({ item_id: preview.itemId, provider: preview.provider, confirm: true }) }); await api("/api/item-intake/handoff", { method: "POST", body: JSON.stringify(payload({ item_id: preview.itemId })) }); $("thread-preview-dialog").close(); state.details.set(preview.itemId, result.imported.item); await load(state.activeBatchId); await openItem(preview.itemId); toast("Thread extracted and sent to Veridex for review."); } catch (error) { $("thread-import-material").disabled = false; $("thread-learn-material").disabled = false; toast(`Thread learning handoff failed: ${error.message}`); } }
async function findEbayListing(id) { const listing = $("detail-ebay-listing").value.trim(); if (!listing) return toast("Enter an eBay item number or listing URL first."); try { const result = await api("/api/ebay-room/listing/find", { method: "POST", body: JSON.stringify(payload({ item_id: id, listing })) }); state.listingLookup = { itemId: id, listing: result.listing }; $("ebay-listing-title").textContent = result.listing.title || "Untitled eBay listing"; $("ebay-listing-price").textContent = money(result.listing.price, result.listing.currency); $("ebay-listing-description").textContent = result.listing.description || "No description returned."; $("ebay-listing-media").textContent = `${result.listing.picture_urls?.length || 0} listing image(s) available.`; const view = $("ebay-listing-view"); view.href = result.listing.listing_url || `https://www.ebay.com/itm/${encodeURIComponent(result.listing.listing_id)}`; $("ebay-listing-dialog").showModal(); } catch (error) { toast(`Listing lookup failed: ${error.message}`); } }
async function applyEbayListing(extractMedia) { const lookup = state.listingLookup; if (!lookup) return; $("apply-ebay-listing").disabled = true; $("apply-ebay-media").disabled = true; try { const result = await api("/api/ebay-room/listing/apply", { method: "POST", body: JSON.stringify(payload({ item_id: lookup.itemId, listing: lookup.listing.listing_id, extract_media: extractMedia })) }); $("ebay-listing-dialog").close(); state.details.set(lookup.itemId, result.applied.item); await load(state.activeBatchId); await openItem(lookup.itemId); toast(extractMedia ? `Listing fields populated and ${result.applied.imported_photo_count || 0} image(s) extracted.` : "Listing fields populated from the verified eBay listing."); } catch (error) { toast(`Listing update failed: ${error.message}`); } finally { $("apply-ebay-listing").disabled = false; $("apply-ebay-media").disabled = false; } }
async function saveListingPhotos(id, assetIds, notice = "Listing photo order saved.") { try { const result = await api("/api/ebay-room/listing-photos", { method: "POST", body: JSON.stringify(payload({ item_id: id, asset_ids: assetIds })) }); state.details.set(id, result.item); await load(state.activeBatchId); toast(notice); await openItem(id); } catch (error) { toast(error.message); } }
