function moveListingPhoto(id, assetId, direction) { const ids = state.currentListingPhotos.map((row) => row.asset_id), index = ids.indexOf(assetId), nextIndex = index + (direction === "up" ? -1 : 1); if (index < 0 || nextIndex < 0 || nextIndex >= ids.length) return; [ids[index], ids[nextIndex]] = [ids[nextIndex], ids[index]]; saveListingPhotos(id, ids); }
