async function saveResearch(id) { const claim = $("research-note").value.trim(); if (!claim) return toast("Write the reviewed finding first."); try { await api("/api/ebay-room/research/attach", { method: "POST", body: JSON.stringify(payload({ item_id: id, claim })) }); state.details.delete(id); await load(state.activeBatchId); await openItem(id); toast("Research note saved with this item."); } catch (error) { toast(error.message); } }
