async function prepareFacebook(id) { const item = await itemDetail(id); if (!(item.listing_photo_asset_ids || []).length) return toast("Choose and order at least one Listing photo before preparing Facebook Marketplace."); if (!item.description?.trim() || item.estimated_value == null) return toast("Add a description and asking price before preparing Facebook Marketplace."); if (!confirm("Copy only this item's ordered Listing photos to the session and fill Facebook Marketplace? You will make the final Publish click.")) return; try { state.data = await api("/api/ebay-room/facebook/prepare", { method: "POST", body: JSON.stringify(payload({ item_id: id })) }); render(); toast("Facebook Marketplace is prepared with the selected listing photo order."); } catch (error) { toast(error.message); } }

