function updateZipControls() { $("item-zip-name").textContent = zipPicker.file ? zipPicker.file.name : "No ZIP selected"; $("item-zip-extract").disabled = !zipPicker.file; $("item-zip-remove").disabled = !zipPicker.file; }
function bindZipControls(id) { const input = $("item-zip-upload"); zipPicker.file = null; $("item-zip-choose").onclick = () => input.click(); input.onchange = () => { zipPicker.file = input.files[0] || null; updateZipControls(); }; $("item-zip-remove").onclick = () => { input.value = ""; zipPicker.file = null; updateZipControls(); }; $("item-zip-extract").onclick = () => extractZip(id, zipPicker.file); updateZipControls(); }
async function extractZip(id, file) { if (!file) return; const limit = Number(state.data?.zip_upload_limit_bytes || 0); if (limit && file.size > limit) return toast(`ZIP is larger than Bob's ${Math.floor(limit / 1024 / 1024)} MB limit.`); $("item-zip-extract").disabled = true; try { const result = await api(`/api/item-intake/items/${id}/extract-zip?name=${encodeURIComponent(file.name)}`, { method: "POST", headers: { "Content-Type": "application/zip" }, body: await file.arrayBuffer() }); if (result.extracted.verified && confirm(`Bob verified ${result.extracted.file_count} extracted files. Delete the original ZIP? The extracted files stay with this item.`)) await api("/api/item-intake/assets/delete", { method: "POST", body: JSON.stringify({ item_id: id, asset_id: result.extracted.archive.asset_id }) }); state.details.delete(id); await load(state.activeBatchId); await openItem(id); toast("Bob unpacked and verified the ZIP contents."); } catch (error) { toast(`ZIP was not unpacked: ${error.message}`); } }

const touchup = { assetId: "" };
function cropOptions() { let left=Math.max(0,Math.min(90,Number($("touchup-left").value)||0)), top=Math.max(0,Math.min(90,Number($("touchup-top").value)||0)), right=Math.max(10,Math.min(100,Number($("touchup-right").value)||100)), bottom=Math.max(10,Math.min(100,Number($("touchup-bottom").value)||100)); if(right-left<10){left=90;right=100} if(bottom-top<10){top=90;bottom=100} $("touchup-left").value=left;$("touchup-top").value=top;$("touchup-right").value=right;$("touchup-bottom").value=bottom; return { left_percent:left, top_percent:top, right_percent:right, bottom_percent:bottom }; }
function renderCropGuide() { const crop = cropOptions(), left = Math.min(crop.left_percent, crop.right_percent - 10), top = Math.min(crop.top_percent, crop.bottom_percent - 10), right = Math.max(crop.right_percent, left + 10), bottom = Math.max(crop.bottom_percent, top + 10); Object.assign($("touchup-crop-guide").style, { left: `${left}%`, top: `${top}%`, width: `${right - left}%`, height: `${bottom - top}%` }); }
