$("refresh").onclick = () => refresh(false); $("new-list").onclick = createList; $("new-item").onclick = createItem; document.querySelectorAll("[data-summary-target]").forEach((button) => { button.onclick = () => jumpToSummary(button.dataset.summaryTarget); }); $("search").oninput = (event) => { state.query = event.target.value.trim().toLowerCase(); render(); }; $("status-filter").onchange = (event) => { state.filter = event.target.value; render(); }; $("board-view").onclick = () => { state.view = "board"; render(); }; $("table-view").onclick = () => { state.view = "table"; render(); }; $("close-touchup").onclick = closeTouchup; $("photo-touchup-dialog").addEventListener("cancel", (event) => { event.preventDefault(); closeTouchup(); }); ["touchup-left", "touchup-top", "touchup-right", "touchup-bottom"].forEach((id) => { $(id).oninput = renderCropGuide; }); $("save-manual-crop").onclick = () => savePhotoTouchup("crop"); $("auto-crop").onclick = () => savePhotoTouchup("auto_crop"); $("auto-adjust").onclick = () => savePhotoTouchup("auto_adjust"); $("apply-ai-touchup").onclick = () => savePhotoTouchup("ai"); $("close-thread-preview").onclick = () => $("thread-preview-dialog").close(); $("thread-import-material").onclick = importThreadMaterial; $("close-ebay-listing").onclick = () => $("ebay-listing-dialog").close(); $("apply-ebay-listing").onclick = () => applyEbayListing(false); $("apply-ebay-media").onclick = () => applyEbayListing(true); bootstrap().catch((error) => toast(error.message));
const touchupAdjustmentIds=["brightness","exposure","highlights","shadows","saturation","warmth","contrast","definition","sharpness"];
const touchupEditor={rotation:0,legacySave:null};
function touchupNumber(name){return Number($("touchup-"+name)?.value||0)}
function touchupOptions(){return {...cropOptions(),rotation:touchupEditor.rotation,...Object.fromEntries(touchupAdjustmentIds.map(name=>[name,touchupNumber(name)]))}}
function touchupDisplay(value){return `${Number(value)>0?"+":""}${Number(value)}`}
function updateTouchupPreview(){const values=touchupOptions();touchupAdjustmentIds.forEach(name=>{const output=$("touchup-"+name+"-value");if(output)output.textContent=touchupDisplay(values[name])});["left","top","right","bottom"].forEach(name=>{const output=$("touchup-"+name+"-value");if(output)output.textContent=`${values[name+"_percent"]}%`});const brightness=Math.max(.25,1+(values.brightness+values.exposure*.65)/120);const contrast=Math.max(.05,1+values.contrast/100+values.definition/200);const saturation=Math.max(0,1+values.saturation/100);const warmth=Math.abs(values.warmth)/180;const hue=values.warmth<0?8:-8;$("touchup-image").style.filter=`brightness(${brightness}) contrast(${contrast}) saturate(${saturation}) sepia(${warmth}) hue-rotate(${hue*warmth}deg)`;$("touchup-image").style.transform=`rotate(${touchupEditor.rotation}deg)`;$("touchup-preview-values").textContent=`${touchupEditor.rotation?`${touchupEditor.rotation}° · `:""}${values.brightness||values.exposure||values.contrast||values.saturation||values.warmth||values.shadows||values.highlights||values.sharpness||values.definition?"Live preview":"Ready to edit"}`;renderCropGuide()}
function resetTouchupValues(group="all"){const groups={light:["brightness","exposure","highlights","shadows"],color:["saturation","warmth"],detail:["contrast","definition","sharpness"]};const names=group==="all"?touchupAdjustmentIds:(groups[group]||[]);names.forEach(name=>{const input=$("touchup-"+name);if(input)input.value=0});if(group==="all"||group==="crop"){["left","top"].forEach(name=>$("touchup-"+name).value=0);["right","bottom"].forEach(name=>$("touchup-"+name).value=100);touchupEditor.rotation=0}updateTouchupPreview()}
function setTouchupTab(tab){document.querySelectorAll("[data-touchup-tab]").forEach(button=>button.classList.toggle("active",button.dataset.touchupTab===tab));document.querySelectorAll("[data-touchup-pane]").forEach(pane=>{pane.hidden=pane.dataset.touchupPane!==tab;pane.classList.toggle("active",pane.dataset.touchupPane===tab)})}
function setTouchupAspect(aspect){document.querySelectorAll("[data-touchup-aspect]").forEach(button=>button.classList.toggle("active",button.dataset.touchupAspect===aspect));if(aspect==="free"){resetTouchupValues("crop");return}const image=$("touchup-image"),width=image.naturalWidth||1,height=image.naturalHeight||1,target={square:1,portrait:4/5,landscape:4/3}[aspect],ratio=width/height;let cropWidth=100,cropHeight=100;if(target<ratio)cropWidth=target/ratio*100;else cropHeight=ratio/target*100;$("touchup-left").value=Math.max(0,Math.round((100-cropWidth)/2));$("touchup-right").value=Math.min(100,Math.round(100-(100-cropWidth)/2));$("touchup-top").value=Math.max(0,Math.round((100-cropHeight)/2));$("touchup-bottom").value=Math.min(100,Math.round(100-(100-cropHeight)/2));updateTouchupPreview()}
function openPhotoTouchupEnhanced(assetId){const asset=(state.details.get(state.activeItemId)?.assets||[]).find(row=>row.asset_id===assetId);if(!asset)return toast("That photo is no longer available.");touchup.assetId=assetId;touchupEditor.rotation=0;$("touchup-source-name").textContent=asset.source_asset_id?`Editing derived photo: ${asset.name}`:`Editing original photo: ${asset.name}`;$("touchup-image").src=imageUrl(assetId);resetTouchupValues();$("ai-touchup-prompt").value="";$("touchup-status").textContent="Adjust the preview, then save a separate photo. The source stays unchanged.";setTouchupTab("crop");$("photo-touchup-dialog").showModal();$("touchup-image").onload=updateTouchupPreview}
async function saveEnhancedTouchup(operation){if(operation!=="adjust")return touchupEditor.legacySave(operation);if(!touchup.assetId)return toast("Choose a photo to touch up first.");const status=$("touchup-status");status.textContent="Saving a separate adjusted photo…";try{const result=await api("/api/item-intake/photos/touch-up",{method:"POST",body:JSON.stringify({item_id:state.activeItemId,asset_id:touchup.assetId,operation:"adjust",options:touchupOptions()})});closeTouchup();state.details.delete(state.activeItemId);await load(state.activeBatchId);await openItem(result.touch_up?.item?.item_id||state.activeItemId);toast("Saved a separate adjusted photo.")}catch(error){status.textContent=error.message;toast(error.message)}}
function setupEnhancedTouchup(){touchupEditor.legacySave=savePhotoTouchup;openPhotoTouchup=openPhotoTouchupEnhanced;savePhotoTouchup=saveEnhancedTouchup;document.querySelectorAll("[data-touchup-tab]").forEach(button=>button.onclick=()=>setTouchupTab(button.dataset.touchupTab));document.querySelectorAll("[data-adjustment]").forEach(input=>input.oninput=updateTouchupPreview);["touchup-left","touchup-top","touchup-right","touchup-bottom"].forEach(id=>$(id).oninput=updateTouchupPreview);document.querySelectorAll("[data-touchup-aspect]").forEach(button=>button.onclick=()=>setTouchupAspect(button.dataset.touchupAspect));document.querySelectorAll("[data-touchup-reset]").forEach(button=>button.onclick=()=>resetTouchupValues(button.dataset.touchupReset));$("reset-touchup-crop").onclick=()=>resetTouchupValues("crop");$("reset-touchup").onclick=()=>resetTouchupValues();document.querySelectorAll("[data-touchup-rotate]").forEach(button=>button.onclick=()=>{touchupEditor.rotation=(touchupEditor.rotation+Number(button.dataset.touchupRotate)+360)%360;updateTouchupPreview()});const light=$("touchup-brightness")?.closest(".touchup-pane");if(light&&!$("touchup-smart-adjust")){const button=document.createElement("button");button.id="touchup-smart-adjust";button.type="button";button.textContent="Auto adjust";button.onclick=()=>touchupEditor.legacySave("auto_adjust");light.append(button)}$("save-adjustments").onclick=()=>saveEnhancedTouchup("adjust");$("apply-ai-touchup").onclick=()=>saveEnhancedTouchup("ai");$("auto-crop").onclick=()=>saveEnhancedTouchup("auto_crop");$("save-manual-crop").onclick=()=>saveEnhancedTouchup("crop");$("auto-adjust").onclick=()=>touchupEditor.legacySave("auto_adjust");updateTouchupPreview()}
window.addEventListener("DOMContentLoaded",setupEnhancedTouchup);

/* Keep the touch-up editor open while local results are saved, and add direct manipulation. */
const touchupFixOriginalPreview=updateTouchupPreview;
function ensureTouchupZoomControl(){if($("touchup-zoom"))return;const pane=document.querySelector('[data-touchup-pane="crop"]'),presets=pane?.querySelector(".touchup-presets");if(!pane||!presets)return;const label=document.createElement("label");label.className="touchup-zoom-control";label.innerHTML='<span>Preview zoom <output id="touchup-zoom-value">100%</output></span><input id="touchup-zoom" type="range" min="100" max="300" value="100">';presets.after(label);const help=document.createElement("p");help.className="touchup-zoom-help";help.textContent="Zoom helps you inspect close-ups; the saved crop still uses the highlighted box.";label.after(help)}
function touchupFixPreview(){ensureTouchupZoomControl();touchupEditor.zoom=Number($("touchup-zoom")?.value||touchupEditor.zoom||100);touchupFixOriginalPreview();const output=$("touchup-zoom-value");if(output)output.textContent=`${touchupEditor.zoom}%`;$("touchup-image").style.transform=`rotate(${touchupEditor.rotation}deg) scale(${touchupEditor.zoom/100})`}
function touchupFixSetAsset(asset){if(!asset)return;touchup.assetId=asset.asset_id;$("touchup-source-name").textContent=asset.source_asset_id?`Editing derived photo: ${asset.name}`:`Editing original photo: ${asset.name}`;$("touchup-image").src=imageUrl(asset.asset_id);$("touchup-image").onload=touchupFixPreview;touchupEditor.zoom=100;resetTouchupValues("all");touchupEditor.zoom=100;ensureTouchupZoomControl();$("touchup-zoom").value=100;touchupFixPreview()}
function touchupPresetControls(){if($("touchup-marketplace-auto"))return;const light=document.querySelector('[data-touchup-pane="light"]');if(light){const button=document.createElement("button");button.id="touchup-marketplace-auto";button.className="primary";button.type="button";button.textContent="Marketplace auto touch-up";button.title="Free local correction with conservative glare softening";button.onclick=()=>touchupFixSaveAndStay("marketplace_auto");light.append(button)}const pane=document.querySelector('[data-touchup-pane="ai"]');if(!pane)return;const heading=pane.querySelector(".touchup-pane-heading"),box=document.createElement("div");box.className="touchup-preset-tools";box.innerHTML='<label>Saved instruction<select id="ai-touchup-preset"><option value="">Choose a saved instruction…</option></select></label><div class="touchup-actions"><input id="ai-touchup-preset-name" maxlength="80" placeholder="Preset name"><button id="save-ai-touchup-preset" type="button">Save instruction</button><button id="delete-ai-touchup-preset" type="button" disabled>Delete</button></div>';heading?.after(box);$("ai-touchup-preset").onchange=()=>{const preset=state.touchupPresets.find(row=>row.preset_id===$("ai-touchup-preset").value);if(preset){$("ai-touchup-prompt").value=preset.prompt;$("ai-touchup-preset-name").value=preset.name}};$("save-ai-touchup-preset").onclick=async()=>{const name=$("ai-touchup-preset-name").value.trim(),prompt=$("ai-touchup-prompt").value.trim();if(!name||!prompt)return toast("Enter a preset name and instruction first.");try{const data=await api("/api/item-intake/touchup-presets",{method:"POST",body:JSON.stringify({name,prompt})});state.touchupPresets=data.presets||[];renderTouchupPresetSelect(name);toast("AI instruction saved.")}catch(error){toast(error.message)}};$("delete-ai-touchup-preset").onclick=async()=>{const id=$("ai-touchup-preset").value;if(!id)return;try{const data=await api("/api/item-intake/touchup-presets",{method:"POST",body:JSON.stringify({action:"delete",preset_id:id})});state.touchupPresets=data.presets||[];renderTouchupPresetSelect();toast("Saved instruction deleted.")}catch(error){toast(error.message)}};renderTouchupPresetSelect()}
function renderTouchupPresetSelect(selectedName=""){const select=$("ai-touchup-preset"),deleteButton=$("delete-ai-touchup-preset");if(!select)return;select.innerHTML='<option value="">Choose a saved instruction…</option>'+state.touchupPresets.map(row=>`<option value="${esc(row.preset_id)}">${esc(row.name)}</option>`).join("");const chosen=state.touchupPresets.find(row=>row.name===selectedName);if(chosen)select.value=chosen.preset_id;if(deleteButton)deleteButton.disabled=!select.value}
async function touchupFixSaveAndStay(operation){if(!touchup.assetId){toast("Choose a photo to touch up first.");return}const itemId=state.activeItemId,payload={item_id:itemId,asset_id:touchup.assetId,operation};if(operation==="crop")payload.options=cropOptions();if(operation==="adjust")payload.options=touchupOptions();if(operation==="ai"){payload.prompt=$("ai-touchup-prompt").value;payload.provider=$("ai-touchup-provider").value;if(!payload.prompt.trim()){toast("Describe the AI touch-up first.");return}const providerName=payload.provider==="cloudflare"?"Cloudflare reference edit":"Codex image tools";if(!confirm(`Send this photo and your instruction to ${providerName}? The original stays in the catalog.`))return;payload.workspace_id=state.workspaceId;payload.session_id=state.sessionId;payload.confirm=true;payload.timeout_seconds=180}const status=$("touchup-status"),button=operation==="ai"?$("apply-ai-touchup"):null;status.textContent=operation==="ai"?"AI is preparing a separate image (up to 3 minutes)…":operation==="marketplace_auto"?"Running free local marketplace touch-up…":"Saving a separate result…";if(button)button.disabled=true;try{const result=await api("/api/item-intake/photos/touch-up",{method:"POST",body:JSON.stringify(payload)});state.details.delete(itemId);await load(state.activeBatchId);await openItem(result.touch_up?.item?.item_id||itemId);touchupFixSetAsset(result.touch_up?.asset);status.textContent="Saved a separate result. Continue editing or close when ready.";toast("Saved a separate touch-up; editor remains open.")}catch(error){status.textContent=operation==="ai"?`AI touch-up failed: ${error.message}`:error.message;toast(status.textContent)}finally{if(button)button.disabled=false}}
const touchupFixOriginalOpen=openPhotoTouchupEnhanced;
openPhotoTouchupEnhanced=function(assetId){touchupFixOriginalOpen(assetId);touchupEditor.zoom=100;ensureTouchupZoomControl();$("touchup-zoom").value=100;touchupFixInstallDrag();touchupFixPreview()};
openPhotoTouchup=openPhotoTouchupEnhanced;
updateTouchupPreview=touchupFixPreview;
saveEnhancedTouchup=touchupFixSaveAndStay;
function setupTouchupFixes(){ensureTouchupZoomControl();$("touchup-zoom").oninput=touchupFixPreview;["touchup-left","touchup-top","touchup-right","touchup-bottom"].forEach(id=>$(id).oninput=touchupFixPreview);touchupFixInstallDrag();const smart=$("touchup-smart-adjust");if(smart)smart.onclick=()=>touchupFixSaveAndStay("auto_adjust");$("auto-adjust").onclick=()=>touchupFixSaveAndStay("auto_adjust");$("reset-touchup").onclick=()=>{resetTouchupValues();touchupEditor.zoom=100;$("touchup-zoom").value=100;touchupFixPreview()};touchupFixPreview()}

function touchupFixInstallDrag(){const guide=$("touchup-crop-guide"),stage=guide?.parentElement;if(!guide||!stage||guide.dataset.dragBound)return;const handle=document.createElement("span");handle.className="touchup-crop-handle";handle.setAttribute("aria-hidden","true");guide.append(handle);let drag=null;const start=event=>{if(drag||event.button!==0)return;const crop=cropOptions(),guideRect=guide.getBoundingClientRect();drag={startX:event.clientX,startY:event.clientY,crop,resize:event.target===handle||(event.clientX>=guideRect.right-24&&event.clientY>=guideRect.bottom-24)};event.preventDefault()};const move=event=>{if(!drag)return;const rect=stage.getBoundingClientRect(),dx=(event.clientX-drag.startX)/rect.width*100,dy=(event.clientY-drag.startY)/rect.height*100,width=drag.crop.right_percent-drag.crop.left_percent,height=drag.crop.bottom_percent-drag.crop.top_percent;if(drag.resize){const aspect=height/Math.max(width,1),newWidth=Math.max(10,Math.min(100-drag.crop.left_percent,width+dx)),newHeight=Math.max(10,Math.min(100-drag.crop.top_percent,newWidth*aspect));$("touchup-right").value=Math.round(drag.crop.left_percent+newWidth);$("touchup-bottom").value=Math.round(drag.crop.top_percent+newHeight)}else{$("touchup-left").value=Math.round(Math.max(0,Math.min(100-width,drag.crop.left_percent+dx)));$("touchup-right").value=Math.round(Number($("touchup-left").value)+width);$("touchup-top").value=Math.round(Math.max(0,Math.min(100-height,drag.crop.top_percent+dy)));$("touchup-bottom").value=Math.round(Number($("touchup-top").value)+height)}touchupFixPreview()};const end=()=>{drag=null};guide.addEventListener("pointerdown",start);window.addEventListener("pointermove",move);window.addEventListener("pointerup",end);guide.addEventListener("mousedown",start);window.addEventListener("mousemove",move);window.addEventListener("mouseup",end);guide.dataset.dragBound="true"}
$("thread-learn-material").onclick = learnThreadMaterial;
function moveTouchupRotateToCrop(){const cropPane=document.querySelector('[data-touchup-pane="crop"]'),rotate=document.querySelector('.touchup-rotate');if(cropPane&&rotate&&!cropPane.contains(rotate))cropPane.querySelector('.touchup-actions')?.before(rotate)}
window.addEventListener("DOMContentLoaded",()=>{moveTouchupRotateToCrop();setupTouchupFixes()});
window.addEventListener("DOMContentLoaded",touchupPresetControls);
document.addEventListener("change",event=>{if(event.target?.id==="ai-touchup-preset")$("delete-ai-touchup-preset").disabled=!event.target.value});

/* Shared-thread listing plans stay separate from the connected-seller lookup. */
function latestChannelDraft(itemId, channel) { const item = (state.data?.board?.items || []).find((row) => row.item_id === itemId); return (item?.channel_drafts || []).find((row) => row.channel === channel)?.payload || {}; }
function marketplaceDraftMarkup(item) { const ebay = latestChannelDraft(item.item_id, "ebay"), facebook = latestChannelDraft(item.item_id, "facebook"); return `<section class="marketplace-drafts"><div class="section-heading compact"><div><p class="eyebrow">Marketplace drafts</p><h3>eBay + Facebook copy</h3><p class="meta">Build editable drafts from a public AI thread. Review every field before saving or preparing a form.</p></div></div><div class="marketplace-draft-grid"><section class="marketplace-draft ebay-draft"><div class="draft-heading"><strong>eBay listing</strong><button id="save-thread-ebay-draft" type="button">Save eBay draft</button></div>${input("Title", "thread-ebay-title", ebay.title || item.title)}${input("Buy It Now price", "thread-ebay-price", ebay.price ?? item.estimated_value, "number")}<label class="detail-field">Description<textarea id="thread-ebay-description" rows="7">${esc(ebay.description || item.description || "")}</textarea></label>${input("Shipping note", "thread-ebay-shipping", ebay.shipping)}${input("Best-offer note", "thread-ebay-offer-note", ebay.offer_note)}${input("Condition", "thread-ebay-condition", ebay.condition)}<label class="detail-field">Item specifics<textarea id="thread-ebay-specifics" rows="4">${esc(ebay.item_specifics || "")}</textarea></label></section><section class="marketplace-draft facebook-draft"><div class="draft-heading"><strong>Facebook Marketplace</strong><button id="save-thread-facebook-draft" type="button">Save Facebook draft</button></div>${input("Title", "thread-facebook-title", facebook.title || item.title)}${input("Local pickup price", "thread-facebook-price", facebook.price ?? item.estimated_value, "number")}${input("Category", "thread-facebook-category", facebook.category || "Home Decor / Wall Art")}${input("Condition", "thread-facebook-condition", facebook.condition || "good")}${input("Location note", "thread-facebook-location", facebook.location)}<label class="detail-field">Description<textarea id="thread-facebook-description" rows="7">${esc(facebook.description || item.description || "")}</textarea></label><p class="meta">Facebook uses the location already set in your Facebook profile.</p><button id="prepare-thread-facebook" class="primary" type="button">Prepare Facebook form</button></section></div></section>`; }
const itemMarkupBeforeMarketplaceDrafts = itemMarkup;
itemMarkup = function(item) { const existing = itemMarkupBeforeMarketplaceDrafts(item); return existing.replace('<h3>Find and populate</h3>', '<h3>Look up connected seller listing</h3>').replace('>Find listing</button>', '>Look up eBay listing</button>').replace('<div class="detail-actions"><button id="save-ebay-draft"', `${marketplaceDraftMarkup(item)}<div class="detail-actions"><button id="save-ebay-draft"`); };
const threadActionsBeforeMarketplaceDrafts = threadActions;
threadActions = function(provider, url) { if (!url) return threadActionsBeforeMarketplaceDrafts(provider, url); if (!isSharedThreadUrl(provider, url)) return threadActionsBeforeMarketplaceDrafts(provider, url); return `<div class="thread-actions"><a class="button" target="_blank" rel="noreferrer" href="${esc(url)}">View thread</a><button data-thread-preview="${provider}" type="button">Preview & extract</button><button data-thread-draft="${provider}" class="primary" type="button">Find listing</button></div>`; };
function marketplaceValue(id) { return $(id)?.value.trim() || ""; }
function marketplaceNumber(id) { const value = marketplaceValue(id); return value === "" ? null : Number(value); }
function ebayThreadDraft() { return { title: marketplaceValue("thread-ebay-title"), description: marketplaceValue("thread-ebay-description"), price: marketplaceNumber("thread-ebay-price"), currency: "USD", shipping: marketplaceValue("thread-ebay-shipping"), offer_note: marketplaceValue("thread-ebay-offer-note"), condition: marketplaceValue("thread-ebay-condition"), item_specifics: marketplaceValue("thread-ebay-specifics"), source_kind: "shared_ai_thread", review_required: true }; }
function facebookThreadDraft() { return { title: marketplaceValue("thread-facebook-title"), description: marketplaceValue("thread-facebook-description"), price: marketplaceNumber("thread-facebook-price"), currency: "USD", category: marketplaceValue("thread-facebook-category"), condition: marketplaceValue("thread-facebook-condition"), location_note: marketplaceValue("thread-facebook-location"), source_kind: "shared_ai_thread", review_required: true }; }
async function saveMarketplaceThreadDraft(id, channel) { const listing = channel === "ebay" ? ebayThreadDraft() : facebookThreadDraft(); if (!listing.title || !listing.description || listing.price == null) return toast(`Add a title, description, and price before saving the ${channel} draft.`); try { state.data = await api("/api/ebay-room/drafts", { method: "POST", body: JSON.stringify(payload({ item_id: id, channel, listing })) }); render(); toast(`${channel === "ebay" ? "eBay" : "Facebook Marketplace"} draft saved. It is still only a local draft.`); } catch (error) { toast(error.message); } }
function applyMarketplacePlan(plan) { const ebay = plan.ebay || {}, facebook = plan.facebook || {}; const set = (id, value) => { if ($(id) && value !== undefined && value !== null) $(id).value = value; }; set("thread-ebay-title", ebay.title); set("thread-ebay-price", ebay.price); set("thread-ebay-description", ebay.description); set("thread-ebay-shipping", ebay.shipping); set("thread-ebay-offer-note", ebay.offer_note); set("thread-ebay-condition", ebay.condition); set("thread-ebay-specifics", ebay.item_specifics); set("thread-facebook-title", facebook.title); set("thread-facebook-price", facebook.price); set("thread-facebook-description", facebook.description); set("thread-facebook-category", facebook.category); set("thread-facebook-condition", facebook.condition); set("thread-facebook-location", facebook.location); }
async function buildMarketplaceDraftsFromThread(id, provider) { const button = document.querySelector(`[data-thread-draft="${CSS.escape(provider)}"]`); if (button) { button.disabled = true; button.textContent = "Finding listing…"; } try { const result = await api("/api/item-intake/threads/listing-plan", { method: "POST", body: JSON.stringify({ item_id: id, provider }) }); applyMarketplacePlan(result.listing_plan?.plan || {}); toast("eBay and Facebook drafts were populated from the shared thread. Review and save them when ready."); } catch (error) { toast(`Could not build marketplace drafts: ${error.message}`); } finally { if (button) { button.disabled = false; button.textContent = "Find listing"; } } }
async function prepareFacebookFromThreadDraft(id) { const listing = facebookThreadDraft(); const item = await itemDetail(id); if (!(item.listing_photo_asset_ids || []).length) return toast("Choose and order at least one Listing photo before preparing Facebook Marketplace."); if (!listing.title || !listing.description || listing.price == null || !listing.category || !listing.condition) return toast("Complete the Facebook title, description, price, category, and condition first."); if (!confirm("Copy this item's ordered Listing photos and these reviewed Facebook fields to Facebook Marketplace? You will make the final Publish click.")) return; try { state.data = await api("/api/ebay-room/facebook/prepare", { method: "POST", body: JSON.stringify(payload({ item_id: id, ...listing })) }); render(); toast("Facebook Marketplace is prepared with the reviewed draft and selected listing photos."); } catch (error) { toast(error.message); } }
const bindItemWorkspaceBeforeMarketplaceDrafts = bindItemWorkspace;
bindItemWorkspace = function(item) { bindItemWorkspaceBeforeMarketplaceDrafts(item); $("save-thread-ebay-draft").onclick = () => saveMarketplaceThreadDraft(item.item_id, "ebay"); $("save-thread-facebook-draft").onclick = () => saveMarketplaceThreadDraft(item.item_id, "facebook"); $("prepare-thread-facebook").onclick = () => prepareFacebookFromThreadDraft(item.item_id); document.querySelectorAll("[data-thread-draft]").forEach((node) => { node.onclick = () => buildMarketplaceDraftsFromThread(item.item_id, node.dataset.threadDraft); }); };
